```js
const { WebClient } = require('@slack/web-client');

function sendMessage(text, channel) {
  const web = new WebClient(process.env.SLACK_BOT_TOKEN);
  const params = {
    text,
    channel,
  };
  return web.chat.postMessage(params).then(() => {
    console.log(`Message sent to ${channel}`);
    return true;
  }).catch((error) => {
    console.error(`Failed to send message: ${error}`);
    return false;
  });
}

// Example usage:
sendMessage("Hello, world!", "#general").then((success) => {
  if (success) {
    console.log("Message sent successfully");
  }
}).catch((error) => {
  console.error("Error sending message:", error);
});
```

To use this function, you need to replace `"#general"` with the name of the Slack channel where you want to post the message, and replace `process.env.SLACK_BOT_TOKEN` with the bot token for your Slack app. You can obtain both of these values from the Slack Developers website.

