            this.authToken = authToken;
            InitializeHttpClient();
        }

        private void InitializeHttpClient()
        {
            httpClient = new HttpClient
            {
                BaseAddress = new Uri(baseUrl),
                Timeout = TimeSpan.FromSeconds(TimeoutInSeconds)
            };
            httpClient.DefaultRequestHeaders.Add(AuthorizationHeaderName, $"Bearer {authToken}");
        }

        protected virtual async Task<TResult> GetAsync<TResult>(string relativeUrl, CancellationToken cancellationToken = default)
        {
            var requestMessage = new HttpRequestMessage(HttpMethod.Get, relativeUrl);
            var responseMessage = await SendAsync(requestMessage, cancellationToken).ConfigureAwait(false);
            return await ExtractContentAsync<TResult>(responseMessage).ConfigureAwait(false);
        }

