1. Create a new React project using `create-react-app`.
2. Install the required dependencies by running `npm install react-toastify` in your terminal.
3. Create a new file called `ToastContext.js` inside a new directory called `contexts`. In this file, define a new context for storing the toast messages and their types.

```javascript
import { createContext } from 'react';

const ToastContext = createContext({
  message: null,
  type: null,
  setMessage: () => {},
  setType: () => {}
});

export default ToastContext;
```

4. Create a new component called `ToastProvider` inside the `contexts` folder. This component will wrap all of our other components and provide access to the `ToastContext` through props.

```javascript
import { ToastContext } from './ToastContext';
import React from 'react';

const ToastProvider = ({ children }) => {
  const [message, setMessage] = React.useState(null);
  const [type, setType] = React.useState(null);

  return (
    <ToastContext.Provider value={{ message, type, setMessage, setType }}>
      {children}
    </ToastContext.Provider>
  );
};

export default ToastProvider;
```

5. Now, import the `ToastProvider` component into your `App.js` file and wrap it around your entire application.

```javascript
import React from 'react';
import ReactDOM from 'react-dom';
import App from './App';
import ToastProvider from './contexts/ToastProvider';

ReactDOM.render(
  <React.StrictMode>
    <ToastProvider>
      <App />
    </ToastProvider>
  </React.StrictMode>,
  document.getElementById('root')
);
```

