import re

def extract_info(sentence, categories):
    info = {}

    for category in categories:
        match = re.search(f"({category})", sentence)
        if match:
            value = match.group(1).strip()

            # Handle special cases for rating and quality
            if category == "rating":
                value = int(value.split()[0])
            elif category == "qual":
                info[category] = list(map(lambda x: x.strip(), value.split("and")))
            else:
                info[category] = value

    return info

