```php
use React\EventLoop\Factory as LoopFactory;
use React\Socket\ConnectionInterface;
use React\Socket\Server as SocketServer;
use React\Socket\ServerOptions;

// Database connection
$dbConn = new PDO('mysql:host=localhost;dbname=my_database', 'my_username', 'my_password');

// Event loop factory
$loop = LoopFactory::create();

// Server options
$options = new ServerOptions([
    'localAddress' => '0.0.0.0', // Listen on all interfaces
    'localPort' => 3000, // Set the port number
]);

// Create server instance
$server = new SocketServer($loop, $options);

// Handle incoming connections
$server->on('connection', function (ConnectionInterface $conn) use ($dbConn) {
    // Save the user ID from the client to the database when they connect
    $userId = $_COOKIE['userId']; // Assuming you have a userId cookie set
    $stmt = $dbConn->prepare("INSERT INTO chatroom_connections (chatroom_id, user_id, conn_id) VALUES (?, ?, ?)");
