    $stmt->bindParam(2, $userId, PDO::PARAM_STR);
    $stmt->bindParam(3, $conn->getRemoteAddress(), PDO::PARAM_STR);
    $stmt->execute();

    // Send a welcome message to the client
    $conn->send("Welcome to the chatroom!\n");
});

// Start the server
$server->listen();

// Run the event loop
$loop->run();
```

